add_expense:
function add_expense(amount, category, note) {
  if (typeof amount !== "number" || !isFinite(amount) || amount <= 0) {
    throw new Error("amount must be a positive number");
  }
  if (category === undefined || category === null || category === "") {
    throw new Error("category is required");
  }
  if (note !== undefined && note !== null && typeof note !== "string") {
    throw new Error("note must be a string");
  }
  state.expenses = state.expenses || [];
  const expense = { amount, category };
  if (typeof note === "string") {
    expense.note = note;
  }
  state.expenses.push(expense);
  return state.expenses.length;
}

total:
function total() {
  const expenses = state.expenses || [];
  let cents = 0;
  for (const e of expenses) {
    cents += Math.round(e.amount * 100);
  }
  return cents / 100;
}

by_category:
function by_category() {
  const expenses = state.expenses || [];
  const cents = {};
  for (const e of expenses) {
    cents[e.category] = (cents[e.category] || 0) + Math.round(e.amount * 100);
  }
  const result = {};
  for (const key of Object.keys(cents)) {
    result[key] = cents[key] / 100;
  }
  return result;
}

set_budget:
function set_budget(category, amount) {
  if (typeof category !== "string" || typeof amount !== "number" || !isFinite(amount) || amount < 0) {
    throw new Error("breaks budgets-shape");
  }
  state.budgets = state.budgets || {};
  state.budgets[category] = amount;
  return amount;
}

over_budget:
function over_budget() {
  const budgets = state.budgets || {};
  const expenses = state.expenses || [];
  const spent = {};
  for (const e of expenses) {
    spent[e.category] = (spent[e.category] || 0) + Math.round(e.amount * 100);
  }
  const over = [];
  for (const cat of Object.keys(budgets)) {
    const overCents = (spent[cat] || 0) - Math.round(budgets[cat] * 100);
    if (overCents > 0) {
      over.push({ category: cat, over: overCents / 100 });
    }
  }
  over.sort(function (a, b) {
    if (b.over !== a.over) return b.over - a.over;
    return a.category < b.category ? -1 : a.category > b.category ? 1 : 0;
  });
  return over.map(function (o) { return o.category; });
}

top_category:
function top_category() {
  const expenses = state.expenses || [];
  const cents = {};
  for (const e of expenses) {
    cents[e.category] = (cents[e.category] || 0) + Math.round(e.amount * 100);
  }
  const cats = Object.keys(cents);
  if (cats.length === 0) return null;
  cats.sort(function (a, b) {
    if (cents[b] !== cents[a]) return cents[b] - cents[a];
    return a < b ? -1 : a > b ? 1 : 0;
  });
  return cats[0];
}
